27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form: a '+' followed by 8 to 15 digits")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "postcode")
55	    private String postcode;
56	
57	    @Column(name = "registration_date")
58	    private LocalDate registrationDate;
59	
60	    @Column(name = "birth_date")
61	    private LocalDate birthDate;
62	
63	    @Column(name = "customer_code")
64	    private String customerCode;
65	
66	    @Column(name = "household_id")
67	    private String householdId;
68	
69	    @Column(name = "namesake_count")
70	    private Integer namesakeCount;
71	
72	    @Column(name = "household_size")
73	    private Integer householdSize;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
85	    private Set<Pet> pets;
86	
87	    public String getAddress() {
88	        return this.address;
89	    }
90	
91	    public void setAddress(String address) {
92	        this.address = address;
93	    }
94	
95	    public String getCity() {
96	        return this.city;
97	    }
98	
99	    public void setCity(String city) {
100	        this.city = city;
101	    }
102	
103	    public String getTelephone() {
104	        return this.telephone;
105	    }
106	
107	    public void setTelephone(String telephone) {
108	        this.telephone = telephone;
109	    }
110	
111	    public String getEmail() {
112	        return this.email;
113	    }
114	
115	    public void setEmail(String email) {
116	        this.email = email;
117	    }
118	
119	    public String getPostcode() {
120	        return this.postcode;
121	    }
122	
123	    public void setPostcode(String postcode) {
124	        this.postcode = postcode;
125	    }
126	
127	    public LocalDate getRegistrationDate() {
128	        return this.registrationDate;
129	    }
130	
131	    public void setRegistrationDate(LocalDate registrationDate) {
132	        this.registrationDate = registrationDate;
133	    }
134	
135	    public LocalDate getBirthDate() {
136	        return this.birthDate;
137	    }
138	
139	    public void setBirthDate(LocalDate birthDate) {
140	        this.birthDate = birthDate;
141	    }
142	
143	    public String getCustomerCode() {
144	        return this.customerCode;
145	    }
146	
147	    public void setCustomerCode(String customerCode) {
148	        this.customerCode = customerCode;
149	    }
150	
151	    public String getHouseholdId() {
152	        return this.householdId;
153	    }
154	
155	    public void setHouseholdId(String householdId) {
156	        this.householdId = householdId;
157	    }
158	
159	    public Integer getNamesakeCount() {
160	        return this.namesakeCount;
161	    }
162	
163	    public void setNamesakeCount(Integer namesakeCount) {
164	        this.namesakeCount = namesakeCount;
165	    }
166	
167	    public Integer getHouseholdSize() {
168	        return this.householdSize;
169	    }
170	
171	    public void setHouseholdSize(Integer householdSize) {
172	        this.householdSize = householdSize;
173	    }
174	
175	    public Boolean getBulkSignupWarning() {
176	        return this.bulkSignupWarning;
177	    }
178	
179	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
180	        this.bulkSignupWarning = bulkSignupWarning;
181	    }
182	
183	    public Boolean getPossibleDuplicate() {
184	        return this.possibleDuplicate;
185	    }
186	
187	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
188	        this.possibleDuplicate = possibleDuplicate;
189	    }
190	
191	    public Integer getPossibleDuplicateOf() {
192	        return this.possibleDuplicateOf;
193	    }
194	
195	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
196	        this.possibleDuplicateOf = possibleDuplicateOf;
197	    }
198	
199	    protected Set<Pet> getPetsInternal() {
200	        if (this.pets == null) {
201	            this.pets = new HashSet<>();
202	        }
203	        return this.pets;
204	    }
205	
206	    protected void setPetsInternal(Set<Pet> pets) {
207	        this.pets = pets;
208	    }
209	
210	    public List<Pet> getPets() {
211	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
212	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
213	        return Collections.unmodifiableList(sortedPets);
214	    }
215	
216	    public void setPets(List<Pet> pets) {
217	        this.pets = new HashSet<>(pets);
218	    }
219	
220	    public void addPet(Pet pet) {
221	        getPetsInternal().add(pet);
222	        pet.setOwner(this);
223	    }
224	
225	    /**
226	     * Return the Pet with the given name, or null if none found for this Owner.
227	     *
228	     * @param name to test
229	     * @return true if pet name is already in use
230	     */
231	    public Pet getPet(String name) {
232	        return getPet(name, false);
233	    }
234	
235	    /**
236	     * Return the Pet with the given name, or null if none found for this Owner.
237	     *
238	     * @param name to test
239	     * @return true if pet name is already in use
240	     */
241	    public Pet getPet(String name, boolean ignoreNew) {
242	        name = name.toLowerCase();
243	        for (Pet pet : getPetsInternal()) {
244	            if (!ignoreNew || !pet.isNew()) {
245	                String compName = pet.getName();
246	                compName = compName.toLowerCase();
247	                if (compName.equals(name)) {
248	                    return pet;
249	                }
250	            }
251	        }
252	        return null;
253	    }
254	
255	    public Pet getPet(Integer petId) {
256	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
257	    }
258	
259	    @Override
260	    public String toString() {
261	        return new ToStringCreator(this)
262	
263	            .append("id", this.getId())
264	            .append("new", this.isNew())
265	            .append("lastName", this.getLastName())
266	            .append("firstName", this.getFirstName())
267	            .append("address", this.address)
268	            .append("city", this.city)
269	            .append("telephone", this.telephone)
270	            .toString();
271	    }
272	}
